import java.util.Scanner;

public class Main {
    static final int N = 266666;
    static final long M = 1000000009L;

    static long[] fac = new long[N];
    static long[] inv = new long[N];
    static long[][] dp = new long[30][22];
    static long[][] a = new long[18][N];
    static long[] b = new long[N];

    static long qpow(long a, long b) {
        long s = a, ans = 1;
        while (b > 0) {
            if ((b & 1) == 1)
                ans = (ans * s) % M;
            b >>= 1;
            s = (s * s) % M;
        }
        return ans;
    }

    public static void main(String[] args) {
        Scanner sc = new Scanner(System.in);
        int n = sc.nextInt();
        int k = sc.nextInt();
        long M_input = sc.nextLong();

        if ((n & 1) == 1) {
            System.out.println(qpow(k, n));
            sc.close();
            return;
        }

        fac[0] = 1;
        for (int i = 1; i <= n; ++i)
            fac[i] = (fac[i - 1] * i) % M;

        inv[n] = qpow(fac[n], M_input - 2);
        for (int i = n - 1; i >= 0; --i)
            inv[i] = (inv[i + 1] * (i + 1)) % M;

        n >>= 1;

        for (int i = 0; i <= n; ++i) {
            int pp = Integer.bitCount(i);
            a[pp][i] = inv[i * 2];
        }

        for (int i = 0; i < 17; ++i)
            for (int j = 0; j < 17; ++j)
                for (int u = 0; u < (1 << 17); ++u)
                    if (((u >> j) & 1) == 1)
                        a[i][u] += a[i][u ^ (1 << j)];

        for (int i = 0; i < 17; ++i)
            for (int u = 0; u < (1 << 17); ++u)
                a[i][u] %= M;

        int pn = Integer.bitCount(n);

        for (int i = 0; i < (1 << 17); ++i) {
            for (int j = 0; j < 30; ++j)
                for (int v = 0; v < 22; ++v)
                    dp[j][v] = 0;
            dp[0][0] = 1;

            for (int j = 1; j <= k; ++j) {
                for (int u = 0; u <= 17; ++u) {
                    for (int v = 0; v <= 17; ++v) {
                        for (int w = 0; w <= 17; ++w) {
                            if (u + v <= 17 && v + w <= 17) {
                                dp[j][u + v] += a[u][i] * dp[j - 1][v];
                                dp[j][u + v] %= M;
                            }
                        }
                    }
                }
            }
            b[i] = dp[k][pn];
        }

        for (int i = 0; i < 17; ++i)
            for (int j = 0; j < (1 << 17); ++j)
                if (((j >> i) & 1) == 1)
                    b[j] -= b[j ^ (1 << i)];

        long result = ((qpow(k, n * 2) - (b[n] % M) * fac[n * 2]) % M + M) % M;
        System.out.println(result);
        sc.close();
    }
}

